function page(title,html){const nativeApk=document.documentElement.classList.contains('wv-native-ui-scale');const isHome=nativeApk&&title==='Centro de operaciones';document.body.classList.toggle('admin-requests-page',nativeApk&&title==='Solicitudes de pasajeros');document.body.classList.toggle('admin-canceled-page',nativeApk&&title==='Anulados');document.body.classList.toggle('admin-trips-page',nativeApk&&title==='Viajes');document.body.classList.toggle('admin-completed-page',nativeApk&&title==='Viajes completos');document.body.classList.toggle('admin-clients-page',nativeApk&&title==='Pasajeros registrados');document.body.classList.toggle('admin-drivers-page',nativeApk&&title==='Conductores');const wallet=$('#admin-wallet'),tools=$('.page-head-tools'),headTitle=$('.page-head-title'),date=$('#today'),profile=$('#admin-profile-open'),topRight=$('.top-right'),logout=$('#admin-logout');if(isHome&&wallet&&headTitle){$('#admin-center-label')?.insertAdjacentElement('afterend',wallet);wallet.classList.add('admin-home-wallet');}else if(wallet&&tools&&wallet.parentElement!==tools){tools.insertBefore(wallet,date||null);wallet.classList.remove('admin-home-wallet');}if(isHome&&profile&&tools&&date){tools.insertBefore(profile,date);profile.classList.add('admin-home-profile');}else if(profile&&topRight&&profile.parentElement!==topRight){topRight.insertBefore(profile,logout||null);profile.classList.remove('admin-home-profile');}const titleEl=$('#page-title');titleEl.textContent=title;titleEl.classList.toggle('admin-requests-title',nativeApk&&title==='Solicitudes de pasajeros');titleEl.style.display=isHome?'none':'';const subtitle=$('#page-subtitle');subtitle.textContent='Centro de operaciones · WEST-VILL';subtitle.style.display=(isHome||(nativeApk&&['Anulados','Viajes','Viajes completos','Pasajeros registrados','Conductores'].includes(title)))?'none':'';const crumb=$('#crumb');if(crumb)crumb.textContent=title;$('#page-content').innerHTML=html}
