async function rows(table,select='*',order='created_at'){const q=sb.from(table).select(select);if(order)q.order(order,{ascending:false});const {data,error}=await q.limit(500);if(error)throw error;return data||[]}
async function loadPeople(){const all=await rows('westvill_profiles','id,username,display_name,role,is_available,created_at','created_at');cache.drivers=all.filter(x=>x.role==='conductor');cache.passengers=all.filter(x=>x.role==='pasajero');$('#driver-badge').textContent=cache.drivers.length;return all}
async function loadStatuses(){const s=await rows('westvill_driver_status','driver_id,status,location_label,notes,created_at','created_at');const seen=new Set();cache.statuses=s.filter(x=>{if(seen.has(x.driver_id))return false;seen.add(x.driver_id);return true;});}
async function loadRequests(){const previous=cache.requests;const next=await rows('westvill_requests','*','created_at');for(const r of next){const before=previous.find(x=>x.id===r.id);if(before){if(r.passenger_followup&&r.passenger_followup!=='ninguna'&&r.passenger_followup!==before.passenger_followup)toast('RESPUESTA DEL PASAJERO: '+(r.passenger_followup==='espero'?'NO HAY PROBLEMA, ESPERO':'YA CONSEGUÍ MÓVIL, MUCHAS GRACIAS'));else if(r.quote_status!==before.quote_status&&['aceptada','pausada','consulta'].includes(r.quote_status))toast('RESPUESTA DEL PASAJERO: '+(r.quote_status==='aceptada'?'ACEPTÓ LA COTIZACIÓN':r.quote_status==='pausada'?'POR AHORA NO':'QUIERE CONSULTAR'));}}cache.requests=next;$('#request-badge').textContent=cache.requests.filter(x=>x.status==='pendiente').length;}
async function checkUnansweredTrips(){
 if(!adminProfile?.id)return;
 const cutoff=new Date(Date.now()-5*60*1000).toISOString();
 const {data,error}=await sb.from('westvill_trips').select('id,passenger_id,driver_id,origin,destination,assigned_at').eq('driver_response','pendiente').is('admin_wait_alerted_at',null).lte('assigned_at',cutoff).limit(50);
 if(error)return;
 for(const trip of data||[]){
  const {data:marked,error:markError}=await sb.from('westvill_trips').update({admin_wait_alerted_at:new Date().toISOString()}).eq('id',trip.id).is('admin_wait_alerted_at',null).select('id').maybeSingle();
  if(markError||!marked)continue;
  const {error:noticeError}=await sb.from('westvill_notifications').insert({user_id:adminProfile.id,title:'Viaje esperando confirmación',body:'El conductor todavía no respondió después de 5 minutos: '+trip.origin+' → '+trip.destination+'. Podés reasignarlo o contactar al pasajero.',kind:'trip_waiting',trip_id:trip.id});
  if(!noticeError)toast('ALERTA: hay un viaje esperando confirmación hace 5 minutos.');
 }
}
function personName(id){return [...cache.drivers,...cache.passengers].find(p=>p.id===id)?.display_name||'Cuenta';}
function adminRatingSummary(id){const r=cache.driverRatings.find(x=>x.driver_id===id);if(!r||!Number(r.rating_count))return '<span class="muted">Sin calificar</span>';const avg=Number(r.average_rating),stars=Array.from({length:5},(_,i)=>{const fill=Math.max(0,Math.min(1,avg-i));return '<span style="font-size:16px;background:linear-gradient(90deg,#ffd21c '+(fill*100)+'%,#536274 '+(fill*100)+'%);-webkit-background-clip:text;background-clip:text;color:transparent">★</span>';}).join('');return '<span class="wv-admin-rating-stars">'+stars+'</span> <b>'+avg.toFixed(1).replace('.',',')+'</b> <small>('+Number(r.rating_count)+')</small>';}
function driverList(filter='all'){const list=filter==='available'?cache.drivers.filter(d=>d.is_available):filter==='unavailable'?cache.drivers.filter(d=>!d.is_available):[...cache.drivers].sort((a,b)=>String(a.display_name||'').localeCompare(String(b.display_name||''),'es-AR',{sensitivity:'base'}));return list.map(d=>{const s=cache.statuses.find(x=>x.driver_id===d.id);return '<tr><td><button class="text-action" data-person="'+d.id+'">'+esc(d.display_name)+'</button><div class="wv-admin-rating">'+adminRatingSummary(d.id)+'</div></td><td>'+esc(prettyUser(d.username))+'</td><td><span class="tag '+(d.is_available?'good':'')+'">'+(d.is_available?'DISPONIBLE':'NO DISPONIBLE')+'</span></td><td><b>'+esc(s?labels[s.status]||s.status:'SIN INFORMAR')+'</b>'+(s?.location_label?'<div class="muted">'+esc(s.location_label)+'</div>':'')+'</td><td>'+fmt(s?.created_at)+'</td></tr>';}).join('')||'<tr><td colspan="5">No hay conductores en esta lista.</td></tr>'}
